package local.pitv;
import android.content.*;import android.database.*;import android.database.MatrixCursor;import android.net.*;import android.os.*;import android.provider.OpenableColumns;import java.io.*;
public class GameFilesProvider extends ContentProvider {
 public boolean onCreate(){return true;}
 File resolve(Uri uri)throws FileNotFoundException{try{File root=new File(getContext().getFilesDir(),"games").getCanonicalFile();String name=uri.getLastPathSegment();if(name==null||!name.matches("(?:game-\\d+\\.(?:nes|smc|sfc|md|gen)|cover-\\d+\\.jpg|preview-\\d+\\.mp4)"))throw new IOException();File file=new File(root,name).getCanonicalFile();if(!file.getParentFile().equals(root)||!file.isFile())throw new IOException();return file;}catch(IOException e){throw new FileNotFoundException("Game file unavailable");}}
 public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{if(!"r".equals(mode))throw new FileNotFoundException("Read only");return ParcelFileDescriptor.open(resolve(uri),ParcelFileDescriptor.MODE_READ_ONLY);}
 String displayName(File file){try{java.io.File catalog=new java.io.File(getContext().getFilesDir(),"games/catalog.json");org.json.JSONArray items=new org.json.JSONArray(new String(java.nio.file.Files.readAllBytes(catalog.toPath()),java.nio.charset.StandardCharsets.UTF_8));for(int i=0;i<items.length();i++){org.json.JSONObject item=items.getJSONObject(i);if(file.getName().equals(item.optString("file"))){String name=file.getName();return item.getString("title")+name.substring(name.lastIndexOf("."));}}}catch(Exception ignored){}return file.getName();} public String getType(Uri uri){return uri.toString().endsWith(".jpg")?"image/jpeg":uri.toString().endsWith(".mp4")?"video/mp4":"application/octet-stream";}
 public Cursor query(Uri uri,String[] projection,String selection,String[] args,String sort){String[] columns=projection==null?new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE}:projection;MatrixCursor cursor=new MatrixCursor(columns);try{File file=resolve(uri);Object[] row=new Object[columns.length];for(int n=0;n<columns.length;n++)row[n]=OpenableColumns.DISPLAY_NAME.equals(columns[n])?displayName(file):OpenableColumns.SIZE.equals(columns[n])?file.length():null;cursor.addRow(row);}catch(Exception ignored){}return cursor;}
 public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}
}
